CREATE DATABASE linkbrief;
USE linkbrief;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE links (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT, long_url TEXT NOT NULL, slug VARCHAR(50) UNIQUE NOT NULL, password_hash VARCHAR(255) DEFAULT NULL, expiry_date DATE DEFAULT NULL, clicks INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE clicks_log (id INT AUTO_INCREMENT PRIMARY KEY, link_id INT NOT NULL, ip_address VARCHAR(45), user_agent TEXT, referrer TEXT, clicked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (link_id) REFERENCES links(id) ON DELETE CASCADE);